/**
 * Web app updates (spec §11 décision 56). Installed from Chrome, the app
 * may stay open for days and keep the old build: the service worker
 * (sw.js, generated by vite.config.ts) changes at each build, the browser
 * installs the new one, which takes over at once (skipWaiting, claim), and
 * the page reloads on controllerchange to run the new build.
 */

type Container = Pick<ServiceWorkerContainer, 'register' | 'controller' | 'addEventListener'>;

export interface UpdateOptions {
  container?: Container;
  reload?: () => void;
  /** A new version was found and is being installed. */
  onUpdateFound?: () => void;
}

export function registerServiceWorker(options: UpdateOptions = {}): void {
  const container = options.container ?? ('serviceWorker' in navigator ? navigator.serviceWorker : undefined);
  if (!container) return;
  const reload = options.reload ?? (() => window.location.reload());

  // Only a worker replacing another reloads the page: the first install's
  // claim() (no controller before) must not, even if the page stays open
  // until the next version.
  let controlled = null !== container.controller;
  let reloading = false;
  container.addEventListener('controllerchange', () => {
    const replaced = controlled;
    controlled = true;
    if (!replaced || reloading) return;
    reloading = true;
    reload();
  });

  container
    .register('/sw.js')
    .then((registration) => {
      registration.addEventListener('updatefound', () => {
        const worker = registration.installing;
        worker?.addEventListener('statechange', () => {
          // « installed » with a controller: an update, not a first install.
          if ('installed' === worker.state && controlled) options.onUpdateFound?.();
        });
      });
      // The app is resumed rather than reopened: ask the server for a new
      // sw.js each time it comes back to the foreground.
      document.addEventListener('visibilitychange', () => {
        if ('visible' === document.visibilityState) void registration.update().catch(() => undefined);
      });
    })
    .catch(() => undefined);
}
